import bpy, math, random, os
from mathutils import Vector
from math import sin, cos, pi
ROOT = os.getcwd()
OUT = os.path.join(ROOT,'output')
os.makedirs(OUT,exist_ok=True)
def mat(name, color, metal=0, rough=.4):
    m=bpy.data.materials.get(name)
    if m: return m
    m=bpy.data.materials.new(name); m.diffuse_color=(*color,1); m.use_nodes=True
    p=m.node_tree.nodes.get('Principled BSDF')
    p.inputs['Base Color'].default_value=(*color,1)
    p.inputs['Metallic'].default_value=metal; p.inputs['Roughness'].default_value=rough
    return m
def finish(o,name,m,smooth=True):
    o.name=name
    if m: o.data.materials.append(m)
    if smooth and o.type=='MESH':
        for p in o.data.polygons:p.use_smooth=True
    return o
def bevel(o,w=.06,n=3):
    m=o.modifiers.new('Soft crafted edges','BEVEL');m.width=w;m.segments=n
    m=o.modifiers.new('Weighted corner normals','WEIGHTED_NORMAL')
    return o
def uv(name,loc,scale,m,seg=24,rings=16):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=seg,ring_count=rings,location=loc)
    o=bpy.context.object;o.scale=scale
    return finish(o,name,m)
def cube(name,loc,scale,m,edge=.04):
    bpy.ops.mesh.primitive_cube_add(size=1,location=loc)
    o=bpy.context.object;o.scale=scale
    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
    finish(o,name,m,False)
    if edge:bevel(o,edge)
    return o
def cyl(name,loc,r,depth,m,verts=64):
    bpy.ops.mesh.primitive_cylinder_add(vertices=verts,radius=r,depth=depth,location=loc)
    return bevel(finish(bpy.context.object,name,m),min(.035,depth*.23),3)
def tube(name,points,r,m):
    cu=bpy.data.curves.new(name,'CURVE');cu.dimensions='3D';cu.resolution_u=12;cu.bevel_depth=r;cu.bevel_resolution=3
    sp=cu.splines.new('BEZIER');sp.bezier_points.add(len(points)-1)
    for p,co in zip(sp.bezier_points,points):p.co=co;p.handle_left_type='AUTO';p.handle_right_type='AUTO'
    o=bpy.data.objects.new(name,cu);bpy.context.collection.objects.link(o);cu.materials.append(m)
    return o
def link(name,a,b,r,m):
    a,b=Vector(a),Vector(b)
    o=cyl(name,(a+b)/2,r,(b-a).length,m,24)
    o.rotation_mode='QUATERNION';o.rotation_quaternion=(b-a).to_track_quat('Z','Y')
    return o
def ring(name,loc,major,minor,m,rotation=None):
    bpy.ops.mesh.primitive_torus_add(major_radius=major,minor_radius=minor,major_segments=96,minor_segments=12,location=loc)
    o=finish(bpy.context.object,name,m)
    if rotation:o.rotation_euler=rotation
    return o
def annulus(name,ro,ri,z,h,m):
    n=128;v=[];f=[]
    for zz in [z-h/2,z+h/2]:
        for r in [ro,ri]:
            v.extend([(r*cos(i*2*pi/n),r*sin(i*2*pi/n),zz) for i in range(n)])
    for i in range(n):
        j=(i+1)%n
        f.extend([(i,j,2*n+j,2*n+i),(n+j,n+i,3*n+i,3*n+j),(2*n+i,2*n+j,3*n+j,3*n+i),(j,i,n+i,n+j)])
    me=bpy.data.meshes.new(name);me.from_pydata(v,[],f);me.update()
    o=bpy.data.objects.new(name,me);bpy.context.collection.objects.link(o)
    return bevel(finish(o,name,m),.045)
def text_obj(name,body,loc,size,m,rot=(pi/2,0,0),extr=.002):
    cu=bpy.data.curves.new(name,'FONT');cu.body=body;cu.align_x='CENTER';cu.align_y='CENTER';cu.size=size;cu.space_character=1.12
    cu.extrude=extr;cu.bevel_depth=.0008;cu.resolution_u=8
    o=bpy.data.objects.new(name,cu);bpy.context.collection.objects.link(o);o.location=loc;o.rotation_euler=rot;cu.materials.append(m)
    return o
def leaf(name,a,b,width,m):
    a,b=Vector(a),Vector(b);d=b-a
    n=Vector((0,0,1))
    if abs(d.normalized().dot(n))>.9:n=Vector((0,1,0))
    side=d.cross(n).normalized()
    normal=side.cross(d).normalized()
    verts=[];faces=[]
    for back in [0,1]:
      for i in range(9):
        t=i/8
        for j in range(5):
          u=(j-2)/2; w=sin(pi*t)**.85*width
          p=a+d*t+side*(u*w)+normal*(sin(pi*t)*(.12*d.length*(1-u*u)-.045*back))
          verts.append(tuple(p))
    for k in [0,45]:
      for i in range(8):
        for j in range(4):
          q=k+i*5+j
          faces.append((q,q+1,q+6,q+5) if k==0 else (q+5,q+6,q+1,q))
    for i in range(8):
      for j in [0,4]:
        q=i*5+j;faces.append((q,q+5,q+50,q+45))
    me=bpy.data.meshes.new(name);me.from_pydata(verts,[],faces);me.update()
    ob=bpy.data.objects.new(name,me);bpy.context.collection.objects.link(ob);finish(ob,name,m)
    return ob

